head.script:
scwin.trigger1_onclick = function(e) {
    dataList2.setJSON([{
        "col1": "aa",
        "col2": "1",
        "rowStatus": "R"
    }, {
        "col1": "bb",
        "col2": "2",
        "rowStatus": "R"
    }, {
        "col1": "cc",
        "col2": "3",
        "rowStatus": "R"
    }, {
        "col1": "dd",
        "col2": "4",
        "rowStatus": "R"
    }, {
        "col1": "ee",
        "col2": "5",
        "rowStatus": "R"
    }, {
        "col1": "ff",
        "col2": "6",
        "rowStatus": "R"
    }]);
    //alert ("데이터 리스트 변경");
    alertShowed = true;
};
scwin.dbClick = function(id) {
    var el = WebSquare.wUnit.getDomById($p.id + id);
    scwin.fireDbClick(el);
}
scwin.fireDbClick = function(node) {
    if (document.createEventObject) {
        node.fireEvent('ondblclick');
    } else if (document.createEvent) {
        var evt = document.createEvent('MouseEvents');
        evt.initEvent('dblclick', true, false);
        node.dispatchEvent(evt);
    } else if (typeof node.ondblclick == 'function') {
        node.ondblclick();
    }
}
scwin.isIE = function() {
    var myNav = navigator.userAgent.toLowerCase();
    return (myNav.indexOf('msie') != -1) ? parseInt(myNav.split('msie')[1]) : false;
}
scwin.getElementsByClassName = function(name) {
    if (scwin.isIE() == 8) {
        return document.querySelectorAll("." + name);
    } else {
        return document.getElementsByClassName(name.replace(/\./g, " "));
    }
}
scwin.unitTest = function() {
    //init
    WebSquare.wUnit.start();
    //Test step 1. 브라우저에서 name3 체크콤보박스의 리스트를 확인한다.
    //1. In the browser, check the list of name3 check combo boxes.
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView1_cell_0_2')");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 1. 11 / 22/ 33 / 44 리스트가 표시된다.
    //1. A list of 11/22/33/44 is displayed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2table_ccb_col_label')[1].innerText == '11'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2table_ccb_col_label')[2].innerText == '22'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2table_ccb_col_label')[3].innerText == '33'", "true");
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getJq('.w2table_ccb_col_label')[4].innerText == '44'", "true");
    //Test step 2. 임의로 데이터를 체크한다.
    //2. Check the data at random.
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView1_cell_0_2')");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_itemTable_3_checkbox').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_itemTable_4_checkbox').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_label').click()");
    //Verify step 2. 선택한 데이터가 체크되어 표시된다.
    //2. The selected data is checked and displayed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_0_2').innerText", "33 44");
    //Test step 3. Data List 버튼을 클릭한다.
    //3. Click the Data List button.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getDomById('trigger1').click()");
    WebSquare.wUnit.addCommand("pause", "500");
    //Verify step 3. 팝업과 함께 동적으로 리스트가 변경된다.
    //3. The list changes dynamically with the popup.
    WebSquare.wUnit.addCommand("assert", "alertShowed", "true");
    //Test step 4. 체크콤보박스의 리스트를 확인한다.
    //4. Check the list of check combo boxes.
    WebSquare.wUnit.addCommand("set", "scwin.dbClick($p.id+'gridView1_cell_1_2')");
    //Verify step 4. 동적으로 변경된 리스트가 표시된다. (전버전에서는 동적으로 변경시에도 기존에 데이터 리스트가 표시되는 현상이 발생)
    //4. The dynamically changed list is displayed. (In previous version, data list is displayed even when changing dynamically)
    WebSquare.wUnit.addCommand("assert", "scwin.getElementsByClassName('w2table_ccb_col_label')[1].innerText", "aa");
    //Test step 5. 임의로 데이터를 체크한다.
    //5. Check the data at random.
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_itemTable_1_checkbox').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_itemTable_2_checkbox').click()");
    WebSquare.wUnit.addCommand("set", "WebSquare.wUnit.getObjById('G_gridView1___checkcombobox_col3_label').click()");
    //Verify step 5. 선택한 데이터가 체크되어 표시된다.
    //5. The selected data is checked and displayed.
    WebSquare.wUnit.addCommand("assert", "WebSquare.wUnit.getObjById('gridView1_cell_1_2').innerText", "aa bb");
    //Run  and stop
    WebSquare.wUnit.run();
    WebSquare.wUnit.stop();
}
